-- READ-ONLY verification AFTER applying 20261109110000_online_contracts.sql. Every row must show ok = true.
select chk, ok from (
  select 1 n, '4 new tables exist' chk, (select count(*) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'clinic_finance' and c.relname in ('contract_templates', 'signature_requests', 'acceptances', 'contract_settings') and c.relkind = 'r') = 4 ok
  union all select 2, 'RLS enabled on all 4', (select count(*) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'clinic_finance' and c.relname in ('contract_templates', 'signature_requests', 'acceptances', 'contract_settings') and c.relrowsecurity) = 4
  union all select 3, 'anon/authenticated have NO table rights', not exists (select 1 from information_schema.role_table_grants where table_schema = 'clinic_finance' and table_name in ('contract_templates', 'signature_requests', 'acceptances', 'contract_settings') and grantee in ('anon', 'authenticated', 'PUBLIC'))
  union all select 4, '6 public RPCs exist (doctor + accountant)', (select count(*) from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = 'public' and p.proname in ('doctor_contract_inbox', 'doctor_contract_decide', 'doctor_consent_accept', 'clinic_finance_contract_signature_command', 'clinic_finance_contract_signature_status', 'clinic_finance_contract_signed_document')) = 6
  union all select 5, 'authenticated can run the doctor + accountant RPCs', has_function_privilege('authenticated', 'public.doctor_contract_inbox()', 'execute') and has_function_privilege('authenticated', 'public.clinic_finance_contract_signature_status()', 'execute')
  union all select 6, 'anon can NOT run them', not has_function_privilege('anon', 'public.doctor_contract_inbox()', 'execute') and not has_function_privilege('anon', 'public.clinic_finance_contract_signature_status()', 'execute') and not has_function_privilege('anon', 'public.clinic_finance_contract_signature_command(text, jsonb, uuid)', 'execute')
  union all select 7, 'internal functions are not executable by authenticated', not has_function_privilege('authenticated', 'clinic_finance.check_signature(text, text)', 'execute') and not has_function_privilege('authenticated', 'clinic_finance.doctor_contract_decide(uuid, boolean, text, text, text, text, text)', 'execute')
  union all select 8, 'the 2 seeded texts are UNPUBLISHED placeholders', (select count(*) from clinic_finance.contract_templates where not published and placeholder) = 2 and (select count(*) from clinic_finance.contract_templates) = 2
  union all select 9, 'both enforcement rules are OFF (no start date)', (select count(*) from clinic_finance.contract_settings where start_date is null) = 2 and (select count(*) from clinic_finance.contract_settings) = 2
  union all select 10, 'no signature requests / acceptances yet', (select count(*) from clinic_finance.signature_requests) = 0 and (select count(*) from clinic_finance.acceptances) = 0
) t order by n;
